public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> result = new ArrayList<>();
    List<Integer> current = new ArrayList<>();
    boolean[] used = new boolean[nums.length];
    class Backtrack {
        void go() {
            if (current.size() == nums.length) {
                result.add(new ArrayList<>(current));
                return;
            }
            for (int i = 0; i < nums.length; i++) {
                if (!used[i]) {
                    used[i] = true;
                    current.add(nums[i]);
                    go();
                    current.remove(current.size() - 1);
                    used[i] = false;
                }
            }
        }
    }
    new Backtrack().go();
    return result;
}

public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }
    // Find the minimum string length among all strings
    int minLen = Integer.MAX_VALUE;
    for (String s : strings) {
        if (s == null) {
            return 0;
        }
        minLen = Math.min(minLen, s.length());
    }
    if (minLen == 0) {
        return 0;
    }

    String first = strings.get(0);
    String revFirst = new StringBuilder(first).reverse().toString();

    // Try lengths from longest to shortest
    for (int len = minLen; len >= 1; len--) {
        // Collect all candidate substrings of this length from first string and its reverse
        Set<String> candidates = new HashSet<>();
        for (int i = 0; i <= first.length() - len; i++) {
            String sub = first.substring(i, i + len);
            candidates.add(sub);
            candidates.add(new StringBuilder(sub).reverse().toString());
        }
        for (int i = 0; i <= revFirst.length() - len; i++) {
            String sub = revFirst.substring(i, i + len);
            candidates.add(sub);
            candidates.add(new StringBuilder(sub).reverse().toString());
        }

        // Check each candidate against all strings
        for (String cand : candidates) {
            String revCand = new StringBuilder(cand).reverse().toString();
            boolean ok = true;
            for (String s : strings) {
                if (!(s.contains(cand) || s.contains(revCand))) {
                    ok = false;
                    break;
                }
            }
            if (ok) {
                return len;
            }
        }
    }
    return 0;
}

