public boolean canArrange(int[] arr, int k) {
    if (arr == null || arr.length % 2 != 0) return false;
    if (k <= 0) return false; // invalid divisor
    int[] freq = new int[k];
    for (int num : arr) {
        int r = ((num % k) + k) % k;
        freq[r]++;
    }
    // remainder 0 must be even
    if (freq[0] % 2 != 0) return false;
    // if k is even, remainder k/2 must be even
    if (k % 2 == 0) {
        if (freq[k / 2] % 2 != 0) return false;
    }
    // check other remainders
    for (int r = 1; r <= k / 2; r++) {
        if (r == k - r) continue; // already handled when k even
        if (freq[r] != freq[k - r]) return false;
    }
    return true;
}

