public int findMinFibonacciNumbers(int k) {
    // Generate Fibonacci numbers up to k
    java.util.List<Integer> fib = new java.util.ArrayList<>();
    fib.add(1);
    fib.add(1);
    while (true) {
        int size = fib.size();
        int next = fib.get(size - 1) + fib.get(size - 2);
        if (next > k) break;
        fib.add(next);
    }

    int count = 0;
    int remaining = k;
    // Greedy: subtract the largest Fibonacci number possible
    for (int i = fib.size() - 1; i >= 0 && remaining > 0; i--) {
        int f = fib.get(i);
        while (remaining >= f) {
            remaining -= f;
            count++;
        }
    }
    return count;
}

public int kthFactor(int n, int k) {
    List<Integer> small = new ArrayList<>();
    List<Integer> large = new ArrayList<>();
    int sqrt = (int) Math.sqrt(n);
    for (int i = 1; i <= sqrt; i++) {
        if (n % i == 0) {
            small.add(i);
            int other = n / i;
            if (other != i) {
                large.add(other);
            }
        }
    }
    int smallCount = small.size();
    int largeCount = large.size();
    if (k <= smallCount) {
        return small.get(k - 1);
    }
    int remaining = k - smallCount;
    if (remaining <= largeCount) {
        // large list is in descending order, so reverse index
        return large.get(largeCount - remaining);
    }
    return -1;
}

