public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    if (low <= 0 && 0 <= high) {
        result.add(0);
    }
    Queue<Long> queue = new LinkedList<>();
    for (int i = 1; i <= 9; i++) {
        if (i > high) {
            continue;
        }
        queue.offer((long) i);
    }
    while (!queue.isEmpty()) {
        long num = queue.poll();
        if (num >= low && num <= high) {
            result.add((int) num);
        }
        if (num > high) {
            continue;
        }
        int lastDigit = (int) (num % 10);
        if (lastDigit > 0) {
            long next = num * 10 + (lastDigit - 1);
            if (next <= high) {
                queue.offer(next);
            }
        }
        if (lastDigit < 9) {
            long next = num * 10 + (lastDigit + 1);
            if (next <= high) {
                queue.offer(next);
            }
        }
    }
    Collections.sort(result);
    return result;
}

