public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return 0;
    }
    int m = mat.length;
    int n = mat[0].length;
    int[][] dpH = new int[m][n];
    int[][] dpV = new int[m][n];
    int[][] dpD = new int[m][n];
    int[][] dpA = new int[m][n];
    int max = 0;
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                dpH[i][j] = (j > 0 ? dpH[i][j - 1] : 0) + 1;
                dpV[i][j] = (i > 0 ? dpV[i - 1][j] : 0) + 1;
                dpD[i][j] = (i > 0 && j > 0 ? dpD[i - 1][j - 1] : 0) + 1;
                dpA[i][j] = (i > 0 && j < n - 1 ? dpA[i - 1][j + 1] : 0) + 1;
                int localMax = Math.max(Math.max(dpH[i][j], dpV[i][j]),
                                         Math.max(dpD[i][j], dpA[i][j]));
                if (localMax > max) {
                    max = localMax;
                }
            } else {
                dpH[i][j] = 0;
                dpV[i][j] = 0;
                dpD[i][j] = 0;
                dpA[i][j] = 0;
            }
        }
    }
    return max;
}

