public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n == 0) return 0;
    // Precompute which pairs sum to a perfect square
    boolean[][] can = new boolean[n][n];
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (i == j) continue;
            int sum = A[i] + A[j];
            int r = (int) Math.sqrt(sum);
            if (r * r == sum) {
                can[i][j] = true;
            }
        }
    }
    int fullMask = (1 << n) - 1;
    int[][] dp = new int[1 << n][n];
    // Initialize starting positions
    for (int i = 0; i < n; i++) {
        dp[1 << i][i] = 1;
    }
    // DP over subsets
    for (int mask = 1; mask <= fullMask; mask++) {
        for (int last = 0; last < n; last++) {
            int cur = dp[mask][last];
            if (cur == 0) continue;
            // Use a set to avoid duplicate values for the next element
            java.util.HashSet<Integer> usedVals = new java.util.HashSet<>();
            for (int next = 0; next < n; next++) {
                if ((mask & (1 << next)) != 0) continue; // already used
                if (!can[last][next]) continue; // sum not a perfect square
                int val = A[next];
                if (usedVals.contains(val)) continue; // skip duplicate value
                usedVals.add(val);
                int nextMask = mask | (1 << next);
                dp[nextMask][next] += cur;
            }
        }
    }
    int result = 0;
    for (int i = 0; i < n; i++) {
        result += dp[fullMask][i];
    }
    return result;
}

public static int largestRectangleArea(int[] heights) {
    int n = heights.length;
    int[] stack = new int[n];
    int top = -1;
    int maxArea = 0;
    for (int i = 0; i <= n; i++) {
        int h = (i == n) ? 0 : heights[i];
        while (top >= 0 && h < heights[stack[top]]) {
            int height = heights[stack[top--]];
            int width = (top == -1) ? i : i - stack[top] - 1;
            int area = height * width;
            if (area > maxArea) {
                maxArea = area;
            }
        }
        if (i < n) {
            stack[++top] = i;
        }
    }
    return maxArea;
}

